AND appeal_no LIKE CONCAT('%', #{appealNo}, '%') AND status = #{status} AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%')) AND is_deleted = 0
ORDER BY create_time DESC LIMIT #{offset}, #{size}

